var text = String(input.transcript || "");
var lines = text.split(/\r?\n/).filter(function (l) { return l.trim() !== ""; });
var actions = lines.filter(function (l) { return /待办|TODO|action|行动|负责|跟进/.test(l); });
var speakers = {};
lines.forEach(function (l) {
  var m = /^([A-Za-z\u4e00-\u9fff]{2,10})[:：]/.exec(l);
  if (m) speakers[m[1]] = (speakers[m[1]] || 0) + 1;
});
var md = "# 会议纪要\n\n## 要点\n" + lines.slice(0, 10).map(function (l) { return "- " + l; }).join("\n");
if (actions.length > 0) md += "\n\n## 待办事项\n" + actions.map(function (a) { return "- " + a; }).join("\n");
return { markdown: md, actionItems: actions, speakerCounts: speakers };
